# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İSLAM\'DA TEMİZLİK ÇEŞİTLERİ: MADDİ · HÜKMÎ · MANEVİ TEMİZLİK (2.2)</text>\n  <rect x="20" y="45" width="210" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">1. Maddi Temizlik</text>\n  <text x="125" y="88" text-anchor="middle" font-size="10" font-weight="bold" fill="#1e3a8a">(Necasetten Tahâret)</text>\n  <text x="125" y="112" text-anchor="middle" font-size="10" fill="#1e3a8a">• Beden temizliği (el, yüz,</text>\n  <text x="125" y="128" text-anchor="middle" font-size="10" fill="#1e3a8a">ağız-diş, tırnak, yıkanma)</text>\n  <text x="125" y="150" text-anchor="middle" font-size="10" fill="#1e3a8a">• Elbise temizliği (Müddessir 4:</text>\n  <text x="125" y="166" text-anchor="middle" font-size="10" fill="#1e3a8a">"Elbiseni tertemiz tut!")</text>\n  <text x="125" y="188" text-anchor="middle" font-size="10" fill="#1e3a8a">• İbadet yeri ve çevre</text>\n  <text x="125" y="204" text-anchor="middle" font-size="10" fill="#1e3a8a">temizliği (Bakara 125)</text>\n  <text x="125" y="226" text-anchor="middle" font-size="10" font-weight="bold" fill="#1d4ed8">Gözle görülen kirden arınma</text>\n\n  <rect x="245" y="45" width="210" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">2. Hükmî Temizlik</text>\n  <text x="350" y="88" text-anchor="middle" font-size="10" font-weight="bold" fill="#14532d">(Hadesten Tahâret)</text>\n  <text x="350" y="112" text-anchor="middle" font-size="10" fill="#14532d">• Gözle görülmeyen, ibadete</text>\n  <text x="350" y="128" text-anchor="middle" font-size="10" fill="#14532d">engel durumdan (hades) arınma</text>\n  <text x="350" y="150" text-anchor="middle" font-size="10" fill="#14532d">• Abdest (Mâide 6: 4 farz)</text>\n  <text x="350" y="170" text-anchor="middle" font-size="10" fill="#14532d">• Gusül / Boy abdesti (3 farz)</text>\n  <text x="350" y="190" text-anchor="middle" font-size="10" fill="#14532d">• Teyemmüm (Su yoksa temiz</text>\n  <text x="350" y="206" text-anchor="middle" font-size="10" fill="#14532d">toprakla: Niyet + 2 darp/mesh)</text>\n  <text x="350" y="226" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">İbadete hazırlık temizliği</text>\n\n  <rect x="470" y="45" width="210" height="195" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="575" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">3. Manevi Temizlik</text>\n  <text x="575" y="88" text-anchor="middle" font-size="10" font-weight="bold" fill="#581c87">(Kalp ve Ahlak Arınması)</text>\n  <text x="575" y="112" text-anchor="middle" font-size="10" fill="#581c87">• Kalbi şirk, nifak ve riyadan</text>\n  <text x="575" y="128" text-anchor="middle" font-size="10" fill="#581c87">uzak tutmak (İhlas)</text>\n  <text x="575" y="150" text-anchor="middle" font-size="10" fill="#581c87">• Kibir, haset, kin, gıybet,</text>\n  <text x="575" y="166" text-anchor="middle" font-size="10" fill="#581c87">yalan ve iftiradan sakınmak</text>\n  <text x="575" y="188" text-anchor="middle" font-size="10" fill="#581c87">• Günahlardan TÖVBE ve</text>\n  <text x="575" y="204" text-anchor="middle" font-size="10" fill="#581c87">İSTİĞFAR ile arınmak</text>\n  <text x="575" y="226" text-anchor="middle" font-size="10" font-weight="bold" fill="#7e22ce">Kalb-i Selîm (Arınmış Kalp)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MANEVİ TEMİZLİK: KALBİ KİRLETEN DUYGULAR VE KARŞIT ERDEMLER</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#fef2f2" stroke="#ef4444" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Kaçınılması Gereken Manevi Kirler</text>\n  <text x="180" y="94" text-anchor="middle" font-size="11" fill="#7f1d1d">• Şirk (Allah\'a ortak koşma) ve Nifak (İkiyüzlülük)</text>\n  <text x="180" y="116" text-anchor="middle" font-size="11" fill="#7f1d1d">• Riya (İbadeti gösteriş için yapma)</text>\n  <text x="180" y="138" text-anchor="middle" font-size="11" fill="#7f1d1d">• Kibir (Kendini üstün görme, büyüklenme)</text>\n  <text x="180" y="160" text-anchor="middle" font-size="11" fill="#7f1d1d">• Haset (Başkasındaki nimeti kıskanma / çekememe)</text>\n  <text x="180" y="182" text-anchor="middle" font-size="11" fill="#7f1d1d">• Gıybet (Arkadan çekiştirme) ve İftira (Suç atma)</text>\n  <text x="180" y="204" text-anchor="middle" font-size="11" fill="#7f1d1d">• Suizan (Kötü zan) ve Tecessüs (Kusur araştırma)</text>\n  <text x="180" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#991b1b">• Yalan, hile, cimrilik ve kul hakkı yeme</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Kalbi Arındıran Güzel Huylar (Tezkiye)</text>\n  <text x="520" y="94" text-anchor="middle" font-size="11" fill="#164e63">• Tevhid (Birlik inancı) ve İhlas (Samimiyet)</text>\n  <text x="520" y="116" text-anchor="middle" font-size="11" fill="#164e63">• Tevazu (Alçakgönüllülük ve hoşgörü)</text>\n  <text x="520" y="138" text-anchor="middle" font-size="11" fill="#164e63">• Gıpta (İmrenme ve kardeşi için hayır dileme)</text>\n  <text x="520" y="160" text-anchor="middle" font-size="11" fill="#164e63">• Hüsnüzan (İyi niyet besleme ve kusur örtme)</text>\n  <text x="520" y="182" text-anchor="middle" font-size="11" fill="#164e63">• Sıdk (Doğruluk), Emanet ve Cömertlik</text>\n  <text x="520" y="204" text-anchor="middle" font-size="11" fill="#164e63">• Şems 9: "Nefsini arındıran kurtuluşa ermiştir."</text>\n  <text x="520" y="224" text-anchor="middle" font-size="11" font-weight="bold" fill="#0e7490">• Şuarâ 89: "Ancak Kalb-i Selîm ile gelen kurtulur."</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">TÖVBE VE İSTİĞFAR İLE MANEVİ ARINMA (TÖVBE-İ NASÛH)</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Tövbe ve İstiğfar Kavramları</text>\n  <text x="180" y="94" text-anchor="middle" font-size="11" fill="#713f12">• Tövbe: İşlenen günahtan pişmanlık duyarak</text>\n  <text x="180" y="112" text-anchor="middle" font-size="11" fill="#713f12">vazgeçmek ve Allah\'a geri dönmektir.</text>\n  <text x="180" y="136" text-anchor="middle" font-size="11" fill="#713f12">• İstiğfar: İşlenen günah ve kusurların</text>\n  <text x="180" y="154" text-anchor="middle" font-size="11" fill="#713f12">Allah tarafından bağışlanmasını dilemektir</text>\n  <text x="180" y="172" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">("Estağfirullah el-Azîm" diyerek af dileme).</text>\n  <text x="180" y="198" text-anchor="middle" font-size="11" font-weight="bold" fill="#a16207">Bakara Suresi 222. Ayet:</text>\n  <text x="180" y="218" text-anchor="middle" font-size="10" fill="#713f12">"Şüphesiz Allah çok tövbe edenleri ve çok temizlenenleri sever."</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Samimi Tövbenin (Tövbe-i Nasûh) 4 Şartı</text>\n  <text x="520" y="96" text-anchor="middle" font-size="11" fill="#14532d">1. İşlenen günahı ve hatayı derhal terk etmek.</text>\n  <text x="520" y="122" text-anchor="middle" font-size="11" fill="#14532d">2. Yaptığı hatadan dolayı kalpten pişmanlık</text>\n  <text x="520" y="138" text-anchor="middle" font-size="11" fill="#14532d">(nedamet) duymak.</text>\n  <text x="520" y="164" text-anchor="middle" font-size="11" fill="#14532d">3. O günaha bir daha dönmemeye kesin karar</text>\n  <text x="520" y="180" text-anchor="middle" font-size="11" fill="#14532d">vermek (azmetmek).</text>\n  <text x="520" y="206" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">4. Kul hakkı varsa hak sahibine hakkını</text>\n  <text x="520" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">ödeyip mutlaka HELALLEŞMEK!</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
